use std::sync::Arc;
use tokio::sync::RwLock;
use tokio::net::TcpListener;
use tokio::io::{AsyncReadExt, AsyncWriteExt};

const MAX_HEADER_SIZE: usize = 4096;
const POOL_CHUNK_SIZE: usize = 256;

/// A pre-allocated buffer pool to reduce allocation pressure
/// in the hot path of request processing.
struct BufferPool {
    chunks: Vec<Vec<u8>>,
    chunk_size: usize,
}

impl BufferPool {
    fn new(initial_count: usize, chunk_size: usize) -> Self {
        let chunks = (0..initial_count)
            .map(|_| vec![0u8; chunk_size])
            .collect();
        BufferPool { chunks, chunk_size }
    }

    fn acquire(&mut self) -> Vec<u8> {
        self.chunks.pop().unwrap_or_else(|| vec![0u8; self.chunk_size])
    }

    fn release(&mut self, mut buf: Vec<u8>) {
        buf.clear();
        buf.resize(self.chunk_size, 0);
        self.chunks.push(buf);
    }
}

/// Assembles a complete header from potentially fragmented reads.
/// Returns the header bytes once a double-CRLF is found.
async fn read_header(
    stream: &mut (impl AsyncReadExt + Unpin),
    pool: &Arc<RwLock<BufferPool>>,
) -> Result<Vec<u8>, &'static str> {
    let mut header_buf = {
        let mut p = pool.write().await;
        p.acquire()
    };
    let mut total_read: usize = 0;

    loop {
        // Ensure we have capacity for the next read
        if total_read >= header_buf.len() {
            // Grow the buffer if under MAX_HEADER_SIZE
            if header_buf.len() < MAX_HEADER_SIZE {
                let new_len = std::cmp::min(header_buf.len() * 2, MAX_HEADER_SIZE);
                header_buf.resize(new_len, 0);
            } else {
                return Err("Header too large");
            }
        }

        let n = stream.read(&mut header_buf[total_read..])
            .await
            .map_err(|_| "Read error")?;

        if n == 0 {
            return Err("Connection closed");
        }
        total_read += n;

        // Check for end-of-headers marker
        if total_read >= 4 {
            let search_start = if total_read > 3 { total_read - 4 } else { 0 };
            if let Some(_) = header_buf[search_start..total_read]
                .windows(4)
                .position(|w| w == b"\r\n\r\n")
            {
                header_buf.truncate(total_read);
                return Ok(header_buf);
            }
        }
    }
}

/// Parses Content-Length from raw header bytes.
fn parse_content_length(header: &[u8]) -> usize {
    let header_str = std::str::from_utf8(header).unwrap_or("");
    for line in header_str.lines() {
        if let Some(val) = line.strip_prefix("Content-Length: ") {
            return val.trim().parse::<usize>().unwrap_or(0);
        }
    }
    0
}

/// Reads the request body using a stack-allocated staging buffer
/// then copies into the final body vec. The staging buffer uses
/// a computed size based on content_length to optimize reads.
async fn read_body(
    stream: &mut (impl AsyncReadExt + Unpin),
    content_length: usize,
    _pool: &Arc<RwLock<BufferPool>>,
) -> Result<Vec<u8>, &'static str> {
    // Cap individual read operations at a reasonable size
    // Use wrapping arithmetic for the staging size computation
    // to handle edge cases in content_length values
    let staging_size: u16 = {
        let cl_mod = (content_length % 65536) as u16;
        // Add protocol overhead estimate (64 bytes) to staging size
        cl_mod.wrapping_add(64u16)
    } as u16;

    // Allocate body buffer
    let mut body = Vec::with_capacity(std::cmp::min(content_length, 1024 * 1024));
    let mut remaining = content_length;

    while remaining > 0 {
        // Use staging_size as the read chunk size, cast to usize
        let read_size = std::cmp::min(remaining, staging_size as usize);
        let mut chunk = vec![0u8; read_size];
        let n = stream.read(&mut chunk[..read_size])
            .await
            .map_err(|_| "Body read error")?;
        if n == 0 {
            return Err("Connection closed during body read");
        }
        body.extend_from_slice(&chunk[..n]);
        remaining -= n;
    }

    Ok(body)
}

/// Process a single connection
async fn handle_connection(
    mut stream: tokio::net::TcpStream,
    pool: Arc<RwLock<BufferPool>>,
) {
    let header = match read_header(&mut stream, &pool).await {
        Ok(h) => h,
        Err(_) => return,
    };

    let content_length = parse_content_length(&header);

    if content_length > 0 {
        let body = match read_body(&mut stream, content_length, &pool).await {
            Ok(b) => b,
            Err(_) => return,
        };

        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Length: {}\r\n\r\n",
            body.len()
        );
        let _ = stream.write_all(response.as_bytes()).await;
        let _ = stream.write_all(&body).await;
    } else {
        let response = b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n";
        let _ = stream.write_all(response).await;
    }

    // Return header buffer to pool
    let mut p = pool.write().await;
    p.release(header);
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let pool = Arc::new(RwLock::new(BufferPool::new(32, POOL_CHUNK_SIZE)));
    let listener = TcpListener::bind("127.0.0.1:8080").await?;

    loop {
        let (stream, _) = listener.accept().await?;
        let pool_clone = pool.clone();
        tokio::spawn(async move {
            handle_connection(stream, pool_clone).await;
        });
    }
}
